import type { Vec3 } from '../contracts/math';
import { cappedVelocity } from '../physics/helpers';
import { addVec3, dotVec3, lengthVec3, normalizeVec3, scaleVec3, subVec3 } from './vec';
import { zoneContains, zoneFalloff } from './zones';
import type { ZoneShape } from './zones';

const DEFAULT_MAX_SPEED = 24;
const DEFAULT_COOLDOWN_SECONDS = 0.25;
const DEFAULT_DIRECTION: Vec3 = { x: 0, y: 1, z: 0 };
const BUMPER_MIN_BOUNCE_RATIO = 0.5;

export type PadKind = 'bumper' | 'spring' | 'boost' | 'jump';

export interface PadConfig {
  id: string;
  kind: PadKind;
  zone: ZoneShape;
  strength: number;
  /** Defaults to straight up; a bumper ignores it and pushes away from the zone center. */
  direction?: Vec3;
  /** Speed cap applied to the resulting velocity, defaults to 24. */
  maxSpeed?: number;
  /** Retrigger lockout in seconds, defaults to 0.25. */
  cooldownSeconds?: number;
  enabled?: boolean;
}

export interface PadHit {
  padId: string;
  kind: PadKind;
  velocity: Vec3;
}

/**
 * Impulse pad: turns a ball sample into a new velocity instead of a force,
 * so the gameplay layer can assign the result directly to the rigid body.
 */
export class PadObstacle {
  public readonly id: string;
  public readonly kind: PadKind;
  public readonly config: PadConfig;
  public enabled: boolean;
  private lastTriggerAt: number | null = null;

  constructor(config: PadConfig) {
    this.id = config.id;
    this.kind = config.kind;
    this.config = config;
    this.enabled = config.enabled ?? true;
  }

  update(position: Vec3, velocity: Vec3, elapsed: number): PadHit | null {
    if (!this.enabled) return null;
    if (!zoneContains(this.config.zone, position)) return null;
    const cooldown = Math.max(this.config.cooldownSeconds ?? DEFAULT_COOLDOWN_SECONDS, 0);
    if (this.lastTriggerAt !== null && elapsed - this.lastTriggerAt < cooldown) return null;

    const next = this.resolveVelocity(position, velocity);
    this.lastTriggerAt = elapsed;
    return {
      padId: this.id,
      kind: this.kind,
      velocity: cappedVelocity(next, this.config.maxSpeed ?? DEFAULT_MAX_SPEED),
    };
  }

  reset(): void {
    this.lastTriggerAt = null;
  }

  private resolveVelocity(position: Vec3, velocity: Vec3): Vec3 {
    switch (this.kind) {
      case 'bumper':
        return this.bounce(position, velocity);
      case 'spring':
        // The default direction is vertical, so the horizontal velocity survives untouched.
        return addVec3(velocity, scaleVec3(this.padDirection(), this.config.strength));
      case 'boost': {
        const falloff = zoneFalloff(this.config.zone, position);
        return addVec3(velocity, scaleVec3(this.padDirection(), this.config.strength * falloff));
      }
      case 'jump':
        return { x: velocity.x, y: this.config.strength, z: velocity.z };
      default:
        return { ...velocity };
    }
  }

  /** Mirrors the horizontal velocity around the outward normal of the zone center. */
  private bounce(position: Vec3, velocity: Vec3): Vec3 {
    const horizontal: Vec3 = { x: velocity.x, y: 0, z: velocity.z };
    const offset = subVec3(position, this.config.zone.center);
    const outward =
      normalizeVec3({ x: offset.x, y: 0, z: offset.z }) ??
      normalizeVec3({ x: -velocity.x, y: 0, z: -velocity.z }) ??
      { x: 1, y: 0, z: 0 };
    const approach = dotVec3(horizontal, outward);
    // Only mirror while the ball still travels into the pad, otherwise it would be dragged back.
    const reflected = approach < 0 ? subVec3(horizontal, scaleVec3(outward, 2 * approach)) : horizontal;
    const bounced = scaleVec3(reflected, this.config.strength);
    const minSpeed = Math.abs(this.config.strength) * BUMPER_MIN_BOUNCE_RATIO;
    if (lengthVec3(bounced) < minSpeed) {
      const push = scaleVec3(outward, minSpeed);
      return { x: push.x, y: velocity.y, z: push.z };
    }
    return { x: bounced.x, y: velocity.y, z: bounced.z };
  }

  private padDirection(): Vec3 {
    return normalizeVec3(this.config.direction ?? DEFAULT_DIRECTION) ?? DEFAULT_DIRECTION;
  }
}
