import { describe, it, expect } from 'vitest';
import { PadObstacle } from './pads';
import type { PadConfig } from './pads';
import { vec3 } from './vec';
import { magnitude } from '../physics/helpers';

const boxZone = { shape: 'box', center: vec3(0, 0, 0), halfExtents: vec3(2, 1, 2) } as const;
const sphereZone = { shape: 'sphere', center: vec3(0, 0, 0), radius: 1 } as const;

function pad(overrides: Partial<PadConfig> & Pick<PadConfig, 'kind'>): PadObstacle {
  return new PadObstacle({ id: 'pad1', zone: boxZone, strength: 5, ...overrides });
}

describe('PadObstacle', () => {
  it('bumper reflects the horizontal velocity away from the zone center', () => {
    const obstacle = pad({ kind: 'bumper', zone: sphereZone, strength: 1.5 });
    const hit = obstacle.update(vec3(0.5, 0, 0), vec3(-4, 0, 0), 0);
    expect(hit).not.toBeNull();
    expect(hit?.padId).toBe('pad1');
    expect(hit?.velocity.x).toBeCloseTo(6);
    expect(hit?.velocity.y).toBeCloseTo(0);
    expect(hit?.velocity.z).toBeCloseTo(0);
  });

  it('bumper keeps a minimum bounce speed of half the strength', () => {
    const obstacle = pad({ kind: 'bumper', zone: sphereZone, strength: 4 });
    const hit = obstacle.update(vec3(0.5, 0, 0), vec3(0, 0, 0), 0);
    expect(hit?.velocity.x).toBeCloseTo(2);
    expect(hit?.velocity.z).toBeCloseTo(0);
  });

  it('spring adds the strength upwards and keeps the horizontal velocity', () => {
    const obstacle = pad({ kind: 'spring', strength: 7 });
    const hit = obstacle.update(vec3(0, 0, 0), vec3(2, 0, -1), 0);
    expect(hit?.velocity.x).toBeCloseTo(2);
    expect(hit?.velocity.y).toBeCloseTo(7);
    expect(hit?.velocity.z).toBeCloseTo(-1);
  });

  it('boost adds the strength along the direction scaled by the zone falloff', () => {
    const obstacle = pad({ kind: 'boost', strength: 5, direction: vec3(1, 0, 0) });
    const center = obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 0);
    expect(center?.velocity.x).toBeCloseTo(5);
    obstacle.reset();
    const edge = obstacle.update(vec3(1, 0, 0), vec3(0, 0, 0), 0);
    expect(edge?.velocity.x).toBeCloseTo(2.5);
  });

  it('jump sets the vertical velocity and keeps the horizontal one', () => {
    const obstacle = pad({ kind: 'jump', strength: 6 });
    const hit = obstacle.update(vec3(0, 0, 0), vec3(3, -2, 1), 0);
    expect(hit?.velocity.x).toBeCloseTo(3);
    expect(hit?.velocity.y).toBeCloseTo(6);
    expect(hit?.velocity.z).toBeCloseTo(1);
  });

  it('cooldown blocks retriggering until it expires', () => {
    const obstacle = pad({ kind: 'jump', strength: 6, cooldownSeconds: 0.5 });
    expect(obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 1)).not.toBeNull();
    expect(obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 1.3)).toBeNull();
    expect(obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 1.6)).not.toBeNull();
  });

  it('reset clears the cooldown', () => {
    const obstacle = pad({ kind: 'spring', strength: 6, cooldownSeconds: 10 });
    expect(obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 0)).not.toBeNull();
    expect(obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 1)).toBeNull();
    obstacle.reset();
    expect(obstacle.update(vec3(0, 0, 0), vec3(0, 0, 0), 1)).not.toBeNull();
  });

  it('clamps the result to maxSpeed', () => {
    const obstacle = pad({ kind: 'jump', strength: 100, maxSpeed: 10 });
    const hit = obstacle.update(vec3(0, 0, 0), vec3(6, 0, 0), 0);
    expect(hit).not.toBeNull();
    expect(magnitude(hit!.velocity)).toBeCloseTo(10);
  });

  it('returns null when disabled or outside the zone', () => {
    const disabled = pad({ kind: 'jump', strength: 6, enabled: false });
    expect(disabled.update(vec3(0, 0, 0), vec3(0, 0, 0), 0)).toBeNull();
    const outside = pad({ kind: 'jump', strength: 6 });
    expect(outside.update(vec3(5, 0, 0), vec3(0, 0, 0), 0)).toBeNull();
  });
});
